from pathlib import Path
import json,html
R=Path(__file__).resolve().parent
reports=json.loads((R/'reports.json').read_text())
style='''*{box-sizing:border-box}body{margin:0;background:#f5f3ed;color:#172b36;font:16px/1.6 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:40px 24px}a{color:inherit}h1{font-size:clamp(32px,5vw,54px);line-height:1.1;letter-spacing:-2px}h2{font-size:23px}small,.muted{color:#53616a}.eyebrow{font:12px monospace;letter-spacing:2px;text-transform:uppercase;color:#a54323}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:16px;margin:32px 0}.metric{border-top:2px solid #172b36;padding:16px 0}.metric strong{display:block;font-size:30px}.panel{background:#fffefa;border:1px solid #dcded6;padding:24px;border-radius:8px;margin:24px 0}select,input,button{padding:10px;border:1px solid #72818a;border-radius:4px;background:#fff;font:inherit;max-width:100%}label{display:inline-block;margin-right:20px;margin-bottom:16px}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:12px 10px;border-bottom:1px solid #ddd}th{font-size:12px;text-transform:uppercase;color:#53616a}td.num{text-align:right;font-variant-numeric:tabular-nums}.scroll{overflow:auto}.barrow{display:grid;grid-template-columns:150px 1fr 100px;gap:12px;align-items:center;margin:12px 0;font-size:13px}.bar{height:16px;background:#1f5961;border-radius:2px}.neg{background:#b95230}.note{border-left:3px solid #b95230;padding-left:16px}footer{margin-top:45px;font-size:13px}@media(max-width:600px){.barrow{grid-template-columns:100px 1fr 65px}.panel{padding:15px}main{padding:24px 16px}}'''
configs=[('retail-sales','retail','Where revenue hides weak profit.','Sample retail data · 2015–2018','Profit is uneven across product groups. Investigate loss-making lines before pursuing more revenue in those groups.','margin','Subcategory','subcategories'),('customer-retention','retention','A return visit needs the right denominator.','Sample retail data · first-observed cohorts','Monthly purchasing is intermittent. Exact-month retention is not subscription survival or cumulative repeat purchase.','retention','Cohort','cohorts'),('nba-player-value','nba','A cheap point is not the whole player.','Lakers · historical 2023–24 snapshot','Low-salary players lead this scoring-cost proxy. That illustrates the effect of contract structure, not a complete ranking of basketball value.','nba','Player','players')]
for slug,key,title,subtitle,finding,kind,label,field in configs:
 d=reports[key]
 if key=='retail':
  k=d['metrics'];metrics=[('Revenue',f"${k['revenue']:,.0f}"),('Profit',f"${k['profit']:,.0f}"),('Weighted margin',f"{k['margin_pct']}%"),('Order lines',f"{k['lines']:,}")]
  controls='<label>Chart metric <select id="metric"><option value="profit">Profit ($)</option><option value="revenue">Revenue ($)</option><option value="margin_pct">Margin (%)</option></select></label>'
  limitation='Descriptive sample data. Profit uses the source definition; shipping overhead and attribution are unverified. Discount effects are associations, not causal estimates.'
  method='Validate line IDs → exclude 806 appended auxiliary rows → parse dates and amounts → aggregate by subcategory → calculate SUM(profit) / SUM(sales).'
 elif key=='retention':
  metrics=[('Customers','793'),('Month 1',f"{d['summary'][1]['retention_pct']}%"),('Month 12',f"{d['summary'][-1]['retention_pct']}%"),('Definition','Exact month')]
  controls='<label>Month after first purchase <select id="offset">'+''.join(f'<option value="{n}" {"selected" if n==1 else ""}>{n}</option>' for n in [0,1,2,3,6,12])+'</select></label>'
  limitation='First purchase means first observed in this file. Previous purchases are unknown. Future cells are omitted, not treated as zero. The final December observation ends on December 30. No acquisition-channel attribution is available.'
  method='Deduplicate customer-month activity → determine first-observed month → build eligible cohort-offset grid → left join activity → divide by cohort size. Observable zero-activity cells are retained.'
 else:
  metrics=[('Salary season','2023–24'),('Input players',str(d['metrics']['input_players'])),('Eligible players',str(d['metrics']['eligible_players'])),('Metric','PPG / $M')]
  controls='<label>Minimum games <input id="games" type="number" min="20" max="82" value="20"></label><label>Minimum minutes/game <input id="minutes" type="number" min="15" max="48" value="15"></label>'
  limitation='Lakers only. Partial-season statistics; exact snapshot cutoff unverified. Salary is annual but points are per game. This metric omits defense, availability, playmaking and contract constraints. Controls tighten the base eligibility filter; excluded raw players are not added back.'
  method='Parse salary currency → require positive salary, at least 20 games and 15 minutes/game → divide PPG by annual salary in millions → rank eligible players.'
 metrics_html=''.join(f'<div class="metric"><span>{a}</span><strong>{b}</strong></div>' for a,b in metrics)
 script='''const D=DATA,K=KIND;const money=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:0}).format(n);function render(){let rows,cols,value,name,unit;if(K==='margin'){let m=document.querySelector('#metric').value;rows=[...D.subcategories].sort((a,b)=>b[m]-a[m]);cols=['subcategory','revenue','profit','margin_pct'];value=m;name='subcategory';unit=m==='margin_pct'?'%':'$';}else if(K==='retention'){let n=+document.querySelector('#offset').value;rows=D.cohorts.filter(r=>r.month_offset===n);cols=['cohort','cohort_size','active_customers','retention_pct'];value='retention_pct';name='cohort';unit='%';}else{let g=+document.querySelector('#games').value,m=+document.querySelector('#minutes').value;rows=D.players.filter(r=>r.games>=g&&r.minutes_per_game>=m);cols=['player','salary','games','points_per_game','points_per_salary_million'];value='points_per_salary_million';name='player';unit='';}const chart=document.querySelector('#chart');chart.replaceChildren();let max=Math.max(1,...rows.map(r=>Math.abs(r[value])));rows.slice(0,24).forEach(r=>{let row=document.createElement('div');row.className='barrow';let lab=document.createElement('span');lab.textContent=r[name];let wrap=document.createElement('div'),bar=document.createElement('div');bar.className='bar'+(r[value]<0?' neg':'');bar.style.width=(Math.abs(r[value])/max*100)+'%';wrap.append(bar);let val=document.createElement('span');val.textContent=(unit==='$'?'$':'')+money(r[value])+(unit==='%'?'%':'');row.append(lab,wrap,val);chart.append(row);});document.querySelector('#count').textContent=rows.length+' rows shown. Chart shows first '+Math.min(24,rows.length)+'. Negative values use rust-colored bars; width represents magnitude.';const table=document.querySelector('#table');table.replaceChildren();let head=document.createElement('thead'),tr=document.createElement('tr');cols.forEach(c=>{let th=document.createElement('th');th.scope='col';th.textContent=c.replaceAll('_',' ');tr.append(th)});head.append(tr);let body=document.createElement('tbody');rows.forEach(r=>{let tr=document.createElement('tr');cols.forEach(c=>{let td=document.createElement('td');td.textContent=typeof r[c]==='number'?r[c].toLocaleString('en-US',{maximumFractionDigits:3}):r[c];tr.append(td)});body.append(tr)});table.append(head,body)}document.querySelectorAll('select,input').forEach(e=>e.addEventListener('input',render));render();'''.replace('DATA',json.dumps(d)).replace('KIND',json.dumps(kind))
 page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{d['title']} | Harin Pinnamaneni</title><style>{style}</style><main><a href="../index.html">← Harin Pinnamaneni / Portfolio</a><p class="eyebrow">{subtitle}</p><h1>{title}</h1><p>{d['title']} · Python / SQLite / Interactive dashboard</p><div class="metrics">{metrics_html}</div><section class="panel"><h2>Explore the results</h2>{controls}<p id="count" class="muted" aria-live="polite"></p><div id="chart" role="img" aria-label="Results chart; exact values in the table below"></div><div class="scroll"><table id="table"></table></div></section><section class="panel"><h2>What I would investigate next</h2><p>{finding}</p><h2>How the analysis works</h2><p>{method}</p><p class="note">{limitation}</p><a href="{html.escape(d['source'])}">View the source data ↗</a></section><footer>Harin Pinnamaneni · AI-assisted portfolio exercise · Generated results, no claimed business impact.</footer></main><script>{script}</script></html>'''
 (R/slug/'dashboard.html').write_text(page)
 readme=f"# {d['title']}\n\n## Business question\n\n{title}\n\n## Explore\n\nOpen [dashboard.html](dashboard.html) in a browser. The dashboard works offline. See [results.json](results.json) for full generated results and [analysis.sql](analysis.sql) for queries.\n\n## Method\n\n{method}\n\n## Interpretation\n\n{finding}\n\n## Limitations\n\n{limitation}\n\n## Reproduce\n\nFrom the parent portfolio folder, run `python build.py` then `python make_dashboards.py`. Python 3.10+, standard library only. Source data and fingerprints are documented in the parent README and results JSON.\n\n## Provenance\n\n{d['source']}\n\nThis is an AI-assisted portfolio exercise. No claim of implemented business impact.\n"
 (R/slug/'README.md').write_text(readme)
print('Generated three standalone dashboards and project READMEs.')
